/**
 * diagnosis/attention-allocator.ts — 注意力配置统计
 *
 * 从已有交互数据中统计团队的认知资源分布。
 * 纯数值计算：关键词聚类 + 频率统计。零 LLM 调用。
 *
 * 数据源（全部已有，不需要新采集）：
 *   - 对话记录中的话题关键词
 *   - 决策类型分布
 *   - Agent 路由方向（内视 vs 外视）
 */
import type { AttentionAllocation } from './types';
/**
 * Record a topic keyword occurrence for a team.
 * Call this from L0 dialogue ingestion or gateway log processing.
 */
export declare function recordTopicKeyword(teamId: string, keyword: string): void;
/**
 * Record a decision type occurrence for a team.
 */
export declare function recordDecisionType(teamId: string, decisionType: string): void;
/**
 * Record an interaction as ops or innovation.
 */
export declare function recordInteraction(teamId: string, type: 'ops' | 'innovation'): void;
/**
 * Record agent consumption for a team.
 */
export declare function recordAgentConsumption(teamId: string, agentId: string): void;
/**
 * Clear all logs for a team.
 */
export declare function clearTeamLogs(teamId: string): void;
/**
 * Compute attention allocation for a team from accumulated log data.
 * Always returns a result (empty defaults if no data).
 */
export declare function computeAttention(teamId: string): AttentionAllocation;
